package cl.eventpass.orders.controller;
import cl.eventpass.orders.model.PurchaseOrder; import cl.eventpass.orders.queue.OrderPublisher; import cl.eventpass.orders.repository.OrderRepository; import cl.eventpass.orders.security.TokenSupport;
import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController {
 private final OrderRepository repo; private final OrderPublisher publisher; public OrderController(OrderRepository r,OrderPublisher p){repo=r;publisher=p;}
 public record CreateRequest(Long eventId,int quantity){}
 @PostMapping public ResponseEntity<PurchaseOrder> create(@RequestBody CreateRequest x,HttpServletRequest request){var user=TokenSupport.require(request,"BUYER");if(x.eventId()==null||x.quantity()<1||x.quantity()>10)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"eventId requerido; quantity debe estar entre 1 y 10");Long buyer=Long.valueOf(user.subject());PurchaseOrder saved=repo.save(new PurchaseOrder(x.eventId(),buyer,x.quantity()));try{publisher.publish(new OrderPublisher.OrderMessage(saved.getId(),saved.getEventId(),saved.getBuyerId(),saved.getQuantity()));}catch(RuntimeException e){saved.setStatus("ERROR_ENCOLADO");repo.save(saved);throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Orden guardada, pero no se pudo enviar a la cola");}return ResponseEntity.status(HttpStatus.ACCEPTED).body(saved);}
 @GetMapping public List<PurchaseOrder> mine(HttpServletRequest request){var c=TokenSupport.require(request,"BUYER");return repo.findByBuyerId(Long.valueOf(c.subject()));}
 @GetMapping("/{id}") public PurchaseOrder get(@PathVariable Long id,HttpServletRequest request){var c=TokenSupport.require(request,"BUYER");PurchaseOrder o=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Orden no encontrada"));if(!o.getBuyerId().equals(Long.valueOf(c.subject())))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"No puedes consultar esta orden");return o;}
 @PatchMapping("/internal/{id}/status") public PurchaseOrder status(@PathVariable Long id,@RequestParam String value){PurchaseOrder o=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Orden no encontrada"));if(!Set.of("EMITIDA","RECHAZADA").contains(value))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Estado inválido");o.setStatus(value);return repo.save(o);}
}
